CREATE TABLE jobs(id TEXT PRIMARY KEY,poster_id TEXT NOT NULL REFERENCES users(id),company TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',location TEXT NOT NULL,skills TEXT NOT NULL DEFAULT '',employment_type TEXT NOT NULL DEFAULT 'full_time',min_experience INTEGER NOT NULL DEFAULT 0,max_experience INTEGER,salary_text TEXT NOT NULL DEFAULT '',source_type TEXT NOT NULL CHECK(source_type IN ('hr','referral','known_source')),apply_by TEXT,posting_status TEXT NOT NULL DEFAULT 'open' CHECK(posting_status IN ('open','closed')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX jobs_search_idx ON jobs(posting_status,created_at);
CREATE TABLE candidates(id TEXT PRIMARY KEY,created_by TEXT NOT NULL REFERENCES users(id),full_name TEXT NOT NULL,mobile TEXT,email TEXT,qualification TEXT NOT NULL DEFAULT '',skills TEXT NOT NULL DEFAULT '',experience_years INTEGER NOT NULL DEFAULT 0,preferred_location TEXT NOT NULL DEFAULT '',consent_confirmed INTEGER NOT NULL CHECK(consent_confirmed=1),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE applications(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(id),candidate_id TEXT NOT NULL REFERENCES candidates(id),submitted_by TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','acknowledged','referred','interview','offered','hired','rejected','withdrawn')),note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(job_id,candidate_id));
CREATE INDEX applications_job_idx ON applications(job_id,status);
CREATE INDEX applications_submitter_idx ON applications(submitted_by,created_at);
